//! Actual Nexus source uses official Prowess identity through generic invocation.
#[path="custom_final_next_wave_support.rs"]mod source_support;
use ironsmith::{CardDefinition,GameState,ObjectId,PlayerId,Zone};
use ironsmith::effects::{EffectContext,execute_effect};
const A:PlayerId=PlayerId(0);const B:PlayerId=PlayerId(1);
fn routes(name:&str)->[CardDefinition;2]{let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/msem-conjure-whole-family-source-inputs.json")).unwrap();let source=fixture["mechanics"][0]["representative_cards"].as_array().unwrap().iter().find(|card|card["name"]==name).unwrap();source_support::definitions(source).unwrap_or_else(|error|panic!("{name}: {error}"))}
fn execute(game:&mut GameState,definition:&CardDefinition,actor:PlayerId){let source=game.create_object_from_definition(definition,actor,Zone::Stack);let mut ctx=EffectContext::new_default(source,actor);let mut events=Vec::new();for effect in definition.spell_effect.as_ref().unwrap().flattened_default_effects(){events.extend(execute_effect(game,effect,&mut ctx).unwrap().events);}for event in events{game.queue_trigger_event(Default::default(),event);}}
fn resolve_triggers(game:&mut GameState,expected:usize){let mut queue=ironsmith::triggers::TriggerQueue::new();let mut dm=ironsmith::decision::SelectFirstDecisionMaker;ironsmith::game_loop::drain_pending_trigger_events_with_dm(game,&mut queue,&mut dm).unwrap();assert_eq!(queue.entries.len(),expected);ironsmith::game_loop::put_triggers_on_stack(game,&mut queue).unwrap();while !game.stack.is_empty(){ironsmith::game_loop::resolve_stack_entry_with(game,&mut dm).unwrap();}}
fn setup(nexus:&CardDefinition)->(GameState,[ObjectId;3]){let mut game=GameState::new(vec!["A".into(),"B".into()],20);let donor=ironsmith_compiler_runtime::compile_to_runtime_definition("Prowess donor","Type: Creature\nPower/Toughness: 1/1\nProwess",false).unwrap();let ids=[game.create_object_from_definition(nexus,A,Zone::Battlefield),game.create_object_from_definition(&donor,A,Zone::Battlefield),game.create_object_from_definition(&donor,B,Zone::Battlefield)];game.take_pending_trigger_events();(game,ids)}
#[test]
fn actual_nexus_invokes_each_controlled_prowess_once_for_an_opponents_creation_batch(){let nexus=routes("Nexus Technician");let creators=routes("Moonlit Lantern Festival");for index in 0..2{let(mut game,[nexus,own,opponent])=setup(&nexus[index]);let before=game.calculated_power(nexus).unwrap();execute(&mut game,&creators[index],B);resolve_triggers(&mut game,2);assert_eq!(game.calculated_power(nexus),Some(before+1));assert_eq!(game.calculated_power(own),Some(2));assert_eq!(game.calculated_power(opponent),Some(1));}}
#[test]
fn zero_created_cards_do_not_invoke_prowess_and_normal_cast_triggers_remain(){for nexus in routes("Nexus Technician"){let(mut game,[source,own,opponent])=setup(&nexus);let blueprint=ironsmith_compiler::compile_supplied_card_definition("Blank design","Type: Sorcery\nGain 1 life.",&[],&[],&[]).unwrap();let empty=ironsmith_compiler::with_supplied_card_definitions(vec![blueprint],||ironsmith_compiler_runtime::compile_to_runtime_definition("Empty creation","Type: Sorcery\nCreate zero real cards named \"Blank design\" in your hand as part of the named conjure action.",false)).unwrap();execute(&mut game,&empty,B);resolve_triggers(&mut game,0);let baseline=game.calculated_power(source).unwrap();let spell=game.create_object_from_definition(&empty,A,Zone::Stack);let event=ironsmith::triggers::TriggerEvent::new(ironsmith::events::SpellCastEvent::new(spell,A,Zone::Hand),Default::default());game.queue_trigger_event(Default::default(),event);resolve_triggers(&mut game,2);assert_eq!(game.calculated_power(source),Some(baseline+1));assert_eq!(game.calculated_power(own),Some(2));assert_eq!(game.calculated_power(opponent),Some(1));}}
